package com.careflow.hospital.reservations;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="slot_reservation") public class SlotReservation {@Id @Column(name="reservation_id")private UUID id;@Column(name="patient_id",nullable=false)private UUID patientId;@Column(name="doctor_id",nullable=false)private UUID doctorId;@Column(name="starts_at",nullable=false)private Instant startsAt;@Column(name="ends_at",nullable=false)private Instant endsAt;@Column(name="expires_at",nullable=false)private Instant expiresAt;@Column(nullable=false)private String status;@Column(name="created_at",nullable=false)private Instant createdAt;protected SlotReservation(){}public SlotReservation(UUID patientId,UUID doctorId,Instant startsAt,Instant endsAt,Instant expiresAt){id=UUID.randomUUID();this.patientId=patientId;this.doctorId=doctorId;this.startsAt=startsAt;this.endsAt=endsAt;this.expiresAt=expiresAt;status="ACTIVE";createdAt=Instant.now();}public void cancel(){if("ACTIVE".equals(status))status="CANCELLED";}public void consume(){if(!"ACTIVE".equals(status)||!expiresAt.isAfter(Instant.now()))throw new IllegalStateException("Reservation is no longer active.");status="CONSUMED";}public UUID getId(){return id;}public UUID getPatientId(){return patientId;}public UUID getDoctorId(){return doctorId;}public Instant getStartsAt(){return startsAt;}public Instant getEndsAt(){return endsAt;}public Instant getExpiresAt(){return expiresAt;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}}
